  '🩺': 'SkinOutlined',
  // 第二轮：操作按钮 / 弹窗类 emoji（2026-09-20 扫描原型残留 63 处）
  '📥': 'DownloadOutlined',
  '🔑': 'KeyOutlined',
  '☁️': 'CloudUploadOutlined',
  '☁': 'CloudUploadOutlined',
  '📶': 'WifiOutlined',
  '♥': 'HeartOutlined',
  '❤': 'HeartOutlined',
  '⚠️': 'WarningOutlined',
  '⚠': 'WarningOutlined',
  '✄': 'ScissorOutlined',
  '🔗': 'LinkOutlined',
  '☑': 'CheckSquareOutlined',
  '☰': 'MenuOutlined',
  '🎥': 'VideoCameraOutlined',
  '↶': 'UndoOutlined',
  '↷': 'RedoOutlined',
  '⛶': 'ExpandOutlined',
